<body>
  <a class="skip-link" href="#main-content">Skip to main content</a>

  <header>
    <div class="brand" aria-label="Northstar Support">
      <span class="brand-mark" aria-hidden="true">N</span>
      <span>Northstar Support</span>
    </div>
  </header>

  <main id="main-content">
    <section class="support-layout" aria-labelledby="page-title">
      <div class="hero-copy">
        <p class="eyebrow">Support request</p>
        <h1 id="page-title">How can we help?</h1>
        <p class="intro">
          Send our team your contact details and a support specialist will reach out with the next steps.
        </p>
      </div>

      <form class="contact-card" id="support-form" novalidate>
        <h2 class="card-heading">Contact information</h2>
        <p class="card-copy">Fields marked required must be completed before sending.</p>

        <div class="form-field">
          <label for="full-name">
            <span>Full name</span>
            <span class="required-note">Required</span>
          </label>
          <input
            id="full-name"
            name="fullName"
            type="text"
            autocomplete="name"
            required>
          <p class="error-text" id="full-name-error"></p>
        </div>

        <div class="form-field">
          <label for="email">
            <span>Email address</span>
            <span class="required-note">Required</span>
          </label>
          <input
            id="email"
            name="email"
            type="email"
            autocomplete="email"
            required>
          <p class="error-text" id="email-error"></p>
        </div>

        <div class="form-field">
          <label for="phone">
            <span>Phone number</span>
            <span class="optional-note">Optional</span>
          </label>
          <input
            id="phone"
            name="phone"
            type="tel"
            autocomplete="tel"
            inputmode="tel"
            aria-describedby="phone-help">
          <p class="helper-text" id="phone-help">Use a 10-digit number, with or without spaces, dashes, or parentheses.</p>
          <p class="error-text" id="phone-error"></p>
        </div>

        <button type="submit">Submit support request</button>
        <p class="form-status" id="form-status" aria-live="polite"></p>
      </form>
    </section>
  </main>

  <script>
    const form = document.querySelector("#support-form");
    const statusMessage = document.querySelector("#form-status");

    const fields = [
      {
        input: document.querySelector("#full-name"),
        error: document.querySelector("#full-name-error"),
        getErrorMessage(input) {
          return input.value.trim() ? "" : "Enter your full name.";
        }
      },
      {
        input: document.querySelector("#email"),
        error: document.querySelector("#email-error"),
        getErrorMessage(input) {
          if (!input.value.trim()) {
            return "Enter your email address.";
          }

          return input.validity.typeMismatch ? "Enter an email address in the format name@example.com." : "";
        }
      },
      {
        input: document.querySelector("#phone"),
        error: document.querySelector("#phone-error"),
        getErrorMessage(input) {
          const digits = input.value.replace(/\D/g, "");
          return input.value.trim() && digits.length !== 10
            ? "Enter a 10-digit phone number, or leave this field blank."
            : "";
        }
      }
    ];

    function setFieldError(field, message) {
      field.error.textContent = message;
      field.input.setAttribute("aria-invalid", message ? "true" : "false");

      const describedBy = field.input.id === "phone" ? ["phone-help"] : [];
      if (message) {
        describedBy.push(field.error.id);
      }

      if (describedBy.length) {
        field.input.setAttribute("aria-describedby", describedBy.join(" "));
      } else {
        field.input.removeAttribute("aria-describedby");
      }
    }

    function validateField(field) {
      const message = field.getErrorMessage(field.input);
      setFieldError(field, message);
      return !message;
    }

    form.addEventListener("submit", (event) => {
      event.preventDefault();
      statusMessage.textContent = "";

      let firstInvalidField = null;
      fields.forEach((field) => {
        if (!validateField(field) && !firstInvalidField) {
          firstInvalidField = field;
        }
      });

      if (firstInvalidField) {
        firstInvalidField.input.focus();
        return;
      }

      statusMessage.textContent = "Thanks. Your support request is ready to send.";
      form.reset();
      fields.forEach((field) => setFieldError(field, ""));
    });

    fields.forEach((field) => {
      field.input.addEventListener("input", () => {
        if (field.input.getAttribute("aria-invalid") === "true") {
          validateField(field);
        }
        statusMessage.textContent = "";
      });
    });
  </script>
